import{c as a,Q as r,j as s,m as o}from"./chunks/framework.W-g_WCNV.js";const p=JSON.parse('{"title":"Password change","description":"How users change their password while logged in.","frontmatter":{"title":"Password change","description":"How users change their password while logged in."},"headers":[],"relativePath":"auth/password-change.md","filePath":"auth/password-change.md"}'),t={name:"auth/password-change.md"};function n(i,e,h,c,d,l){return r(),s("div",null,[...e[0]||(e[0]=[o('<p>Logged-in users can change their password at <code>/profile/password</code>.</p><h2 id="what-s-required" tabindex="-1">What&#39;s required <a class="header-anchor" href="#what-s-required" aria-label="Permalink to &quot;What&#39;s required&quot;">​</a></h2><p>To change your password, you need:</p><ol><li>Your current password (so someone who steals your session cookie cannot change your password).</li><li>The new password, entered twice to confirm.</li><li>If you have a TOTP authenticator app enrolled, your current 6-digit code is also required.</li></ol><h2 id="what-happens-after-a-successful-change" tabindex="-1">What happens after a successful change <a class="header-anchor" href="#what-happens-after-a-successful-change" aria-label="Permalink to &quot;What happens after a successful change&quot;">​</a></h2><ul><li>All sessions except the current one are invalidated. This means any other device or browser where you were logged in will be signed out.</li><li>GateKeeper sends a notification email to your address confirming the change.</li><li>The event is recorded in the audit log.</li></ul><h2 id="forced-password-change" tabindex="-1">Forced password change <a class="header-anchor" href="#forced-password-change" aria-label="Permalink to &quot;Forced password change&quot;">​</a></h2><p>When an admin creates an account or directly sets a password, the user is required to change it on their next login. The application redirects them to <code>/profile/password?forced=1</code> before they can access anything else.</p><h2 id="minimum-password-length" tabindex="-1">Minimum password length <a class="header-anchor" href="#minimum-password-length" aria-label="Permalink to &quot;Minimum password length&quot;">​</a></h2><p>The requirements come from your <a href="/security/password-policy.html">password policy</a> and are enforced on the server. The <code>minlength</code> attribute on the form reflects the same configured minimum, but it is a convenience hint only and is not what enforces the rule.</p>',10)])])}const g=a(t,[["render",n]]);export{p as __pageData,g as default};
